namespace Quantum.Entanglement {
    open Microsoft.Quantum.Canon;
    open Microsoft.Quantum.Intrinsic;
    open Microsoft.Quantum.Measurement;

    @EntryPoint()
    operation CreateBellState() : (Result, Result) {
        use (q1, q2) = (Qubit(), Qubit());

        // Create |Φ⁺⟩ = (|00⟩ + |11⟩)/√2
        H(q1);           // Put q1 in |+⟩
        CNOT(q1, q2);    // Entangle with q2

        // Measure both
        let result1 = M(q1);
        let result2 = M(q2);

        // Results should be correlated
        Message($"Qubit 1: {result1}, Qubit 2: {result2}");
        Message($"Correlated: {result1 == result2}");

        return (result1, result2);
    }

    operation TestDifferentBases() : Unit {
        use (q1, q2) = (Qubit(), Qubit());

        // Create Bell pair
        H(q1);
        CNOT(q1, q2);

        // Measure in X basis (apply H before measurement)
        H(q1);
        H(q2);

        let (r1, r2) = (M(q1), M(q2));
        Message($"X basis measurement - Q1: {r1}, Q2: {r2}");
    }
}
